// Runtime-composed source module. Keep declarations in shared application scope.
// B1F WIP: 工地用料單、系統五金預估、其他叫料與既有購物車／退貨串接。
function ensureB1FSiteMaterialTestData(){
  if(!localTestMode)return;
  const store=b1fDataV3();
  if(store.items.length)return;
  const now=b1fNow();
  store.items.push(
    {id:'local-b1f-hinge',name:'緩衝鉸鍊',categoryIds:[],stockQty:60,unit:'個',unitPrice:85,source:'本機測試資料',note:'僅供系統五金預估測試',createdAt:now},
    {id:'local-b1f-rail',name:'抽屜滑軌',categoryIds:[],stockQty:24,unit:'組',unitPrice:320,source:'本機測試資料',note:'僅供系統五金預估測試',createdAt:now},
    {id:'local-b1f-screw',name:'系統櫃螺絲',categoryIds:[],stockQty:500,unit:'支',unitPrice:2,source:'本機測試資料',note:'僅供系統五金預估測試',createdAt:now}
  );
  b1fSaveV3();
}
function b1fSiteMaterialListMarkup(){return b1fSiteMaterialListMarkupV1();}
function b1fSiteMaterialListMarkupV1(){return `<section style="max-width:760px;border:1px solid #ddd5ee;border-radius:12px;background:#fff;padding:22px"><h2 style="margin:0;color:#503c78;font-size:18px">工地用料單</h2><p style="margin:8px 0 0;color:var(--text2);font-size:13px;line-height:1.65">這裡將集中管理各工地的用料規劃；B1F 商城的商品、庫存、領用與退貨流程維持在原本頁籤中。</p><div style="margin-top:18px;padding:16px;border:1px dashed #cfc3e4;border-radius:9px;background:#faf8ff;color:#705e92;font-size:13px">工地用料單已建立入口。五金預估、其他叫料、領用、退貨與表格功能會在後續分項加入。</div></section>`;}
function renderB1FSiteMaterials(){const el=$('panel-b1f');if(!el)return;const cartLabel=`購物車${b1fCartCount()?` ${b1fCartCount()}`:''}`,tabs=[['entry','新增商品'],['products','商品'],['cart',cartLabel],['return','退貨'],['pending','待結案'],['history','紀錄']],views={entry:b1fEntryMarkup,products:b1fProductsMarkup,cart:b1fCartMarkup,return:b1fReturnMarkup,pending:b1fPendingMarkup,history:b1fHistoryMarkup};el.innerHTML=`<div class="b1f-shell"><div class="b1f-head"><div><h1>🛒 B1F 商城</h1><p>工程剩料、可再利用商品與常備五金；計價只記錄在 B1F 與工地使用紀錄。</p></div><div style="display:flex;align-items:center;justify-content:flex-end;gap:10px;flex-wrap:wrap"><div><button type="button" aria-label="新增工地用料單" class="${b1fView==='site-material-list'?'active':''}" style="min-height:34px;border:0;border-radius:6px;background:${b1fView==='site-material-list'?'#fff':'transparent'};color:${b1fView==='site-material-list'?'#8d3030':'#9e5757'};font:600 13px inherit;padding:6px 10px;cursor:pointer" onclick="setB1FView('site-material-list')">＋新增工地用料單</button></div><div class="b1f-tabs">${tabs.map(([id,label])=>`<button class="${b1fView===id?'active':''}" onclick="setB1FView('${id}')">${label}</button>`).join('')}</div></div></div>${b1fFlash?`<div class="b1f-summary" style="margin-bottom:12px">${escAttr(b1fFlash)}</div>`:''}${b1fView==='site-material-list'?b1fSiteMaterialListMarkupV2():views[b1fView]()}</div>`;b1fFlash='';}
renderB1F=renderB1FSiteMaterials;window.renderB1F=renderB1F;
if(!document.getElementById('b1f-site-material-entry-style'))document.head.insertAdjacentHTML('beforeend','<style id="b1f-site-material-entry-style">#panel-b1f button[aria-label="新增工地用料單"]{background:#9e5757!important;color:#fff!important}</style>');

// 工地用料單：預估需求獨立保存，只引用 B1F 商品作為欄位，不會異動庫存。
let b1fSiteMaterialListId='';
function b1fSiteMaterialLists(){const store=b1fData();return(store.siteMaterialLists||=([]));}
function b1fSiteMaterialCurrent(){return b1fSiteMaterialLists().find(list=>list.id===b1fSiteMaterialListId)||null;}
function b1fSiteMaterialSave(){b1fSave();}
function b1fSiteMaterialNumber(value){const number=Number(value);return Number.isFinite(number)&&number>0?number:0;}
function b1fSiteMaterialTotal(list,itemId){return list.rows.reduce((total,row)=>total+(Number(row.quantities?.[itemId])||0),0);}
function b1fSiteMaterialListMarkupV2(){const current=b1fSiteMaterialCurrent(),lists=b1fSiteMaterialLists();if(current)return b1fSiteMaterialDetailMarkup(current);const projects=S.projects.filter(project=>project.status==='prog');return '<section style="max-width:860px;border:1px solid #efd6d6;border-radius:12px;background:#fff;padding:22px"><h2 style="margin:0;color:#7d3030;font-size:18px">工地用料單</h2><p style="margin:8px 0 18px;color:var(--text2);font-size:13px;line-height:1.65">系統五金預估只記錄需求數量，不會扣除 B1F 庫存。請直接選擇施工中的案件查看用料單。</p><div><div style="font-size:13px;font-weight:700;color:var(--text2);margin-bottom:8px">施工中的工地用料單</div><div style="display:grid;gap:8px">'+(projects.length?projects.map(project=>{const list=lists.find(row=>row.projectId===project.id);return '<button class="btn" type="button" style="justify-content:space-between;text-align:left" onclick="openOrCreateB1FSiteMaterialList(\''+escAttr(project.id)+'\')"><span>'+escAttr(project.name)+'</span><span style="color:var(--text2)">'+(list?list.rows.length+' 個圖紙頁數／項目':'尚未建立用料單')+'</span></button>';}).join(''):'<div class="b1f-empty">目前沒有施工中案件。</div>')+'</div></div></section>';}
function b1fSiteMaterialDetailMarkup(list){const items=b1fData().items;const header=items.map(item=>'<th style="min-width:132px;padding:10px;text-align:center;font-size:12px;color:#7d3030;border-bottom:1px solid #efdede">'+escAttr(item.name)+'<div style="margin-top:3px;font-weight:400;color:var(--text3)">預估數量</div></th>').join('');const rows=list.rows.map(row=>'<tr><td style="min-width:185px;padding:7px;border-bottom:1px solid #f2e6e6"><div style="display:flex;gap:6px"><input class="b1f-input" style="min-height:34px" value="'+escAttr(row.label)+'" aria-label="圖紙頁數或項目" onchange="updateB1FSiteMaterialRowLabel(\''+list.id+'\',\''+row.id+'\',this.value)"><button class="btn btn-sm btn-danger" type="button" aria-label="刪除此圖紙頁數或項目" onclick="deleteB1FSiteMaterialRow(\''+list.id+'\',\''+row.id+'\')">刪除</button></div></td>'+items.map(item=>'<td style="padding:7px;text-align:center;border-bottom:1px solid #f2e6e6"><input class="b1f-row-qty" style="min-width:92px" type="number" min="0" step="any" value="'+(Number(row.quantities?.[item.id])||0)+'" aria-label="'+escAttr(row.label)+' '+escAttr(item.name)+' 預估數量" oninput="updateB1FSiteMaterialQuantity(\''+list.id+'\',\''+row.id+'\',\''+item.id+'\',this.value)"></td>').join('')+'</tr>').join('');const totals=items.map(item=>'<td data-b1f-estimate-total="'+escAttr(item.id)+'" style="padding:10px;text-align:center;background:#fff8f8;color:#8d3030;font-weight:700;border-top:1px solid #efdede">'+b1fSiteMaterialTotal(list,item.id)+'</td>').join('');return '<section style="max-width:100%;border:1px solid #efd6d6;border-radius:12px;background:#fff;padding:22px"><div style="display:flex;justify-content:space-between;gap:12px;align-items:start;flex-wrap:wrap"><div><button class="btn btn-sm" type="button" onclick="closeB1FSiteMaterialList()">← 所有工地用料單</button><h2 style="margin:12px 0 0;color:#7d3030;font-size:18px">'+escAttr(list.projectName)+'｜系統五金預估</h2><p style="margin:7px 0 0;color:var(--text2);font-size:13px">此表僅記錄設計／施工前的預估需求，修改不會影響 B1F 商品庫存、購物車、領用、退貨或金額。</p></div><button class="btn btn-p" type="button" onclick="addB1FSiteMaterialRow(\''+list.id+'\')">＋新增圖紙頁數／項目</button></div>'+(items.length?'<div style="margin-top:18px;overflow:auto;border:1px solid #efd6d6;border-radius:9px"><table style="border-collapse:collapse;width:max-content;min-width:100%"><thead><tr><th style="position:sticky;left:0;z-index:1;min-width:205px;padding:10px;text-align:left;background:#fff8f8;color:#7d3030;font-size:12px;border-bottom:1px solid #efdede">圖紙頁數／項目</th>'+header+'</tr></thead><tbody>'+rows+'</tbody><tfoot><tr><td style="position:sticky;left:0;z-index:1;padding:10px;background:#fff8f8;color:#7d3030;font-weight:700;border-top:1px solid #efdede">預估總數量</td>'+totals+'</tr></tfoot></table></div>':'<div class="b1f-empty" style="margin-top:18px">目前 B1F 尚無商品，請先在「新增商品」建立系統五金品項後再填寫預估數量。</div>')+'</section>';}
window.createB1FSiteMaterialList=function(){const projectId=$('b1f-site-project')?.value,project=S.projects.find(row=>row.id===projectId);if(!project)return alert('請先選擇施工中案件。');const existing=b1fSiteMaterialLists().find(list=>list.projectId===projectId);if(existing){b1fSiteMaterialListId=existing.id;renderB1F();return;}const list={id:b1fId('site_material'),projectId:project.id,projectName:project.name,rows:[],createdAt:b1fNow(),updatedAt:b1fNow()};b1fSiteMaterialLists().push(list);b1fSiteMaterialSave();b1fSiteMaterialListId=list.id;renderB1F();};
window.openOrCreateB1FSiteMaterialList=function(projectId){const project=S.projects.find(row=>row.id===projectId);if(!project)return;const existing=b1fSiteMaterialLists().find(list=>list.projectId===projectId);if(existing){openB1FSiteMaterialList(existing.id);return;}const list={id:b1fId('site_material'),projectId:project.id,projectName:project.name,rows:[],createdAt:b1fNow(),updatedAt:b1fNow()};b1fSiteMaterialLists().push(list);b1fSiteMaterialSave();b1fSiteMaterialListId=list.id;renderB1F();};
window.openB1FSiteMaterialList=function(id){b1fSiteMaterialListId=id;renderB1F();};
window.closeB1FSiteMaterialList=function(){b1fSiteMaterialListId='';renderB1F();};
window.addB1FSiteMaterialRow=function(listId){const list=b1fSiteMaterialLists().find(row=>row.id===listId);if(!list)return;list.rows.push({id:b1fId('drawing'),label:'圖紙第 '+(list.rows.length+1)+' 頁',quantities:{}});list.updatedAt=b1fNow();b1fSiteMaterialSave();renderB1F();};
window.deleteB1FSiteMaterialRow=function(listId,rowId){const list=b1fSiteMaterialLists().find(row=>row.id===listId);if(!list||!confirm('確定刪除此圖紙頁數／項目？'))return;list.rows=list.rows.filter(row=>row.id!==rowId);list.updatedAt=b1fNow();b1fSiteMaterialSave();renderB1F();};
window.updateB1FSiteMaterialRowLabel=function(listId,rowId,value){const list=b1fSiteMaterialLists().find(row=>row.id===listId),row=list?.rows.find(item=>item.id===rowId);if(!row)return;row.label=value.trim()||'未命名項目';list.updatedAt=b1fNow();b1fSiteMaterialSave();};
window.updateB1FSiteMaterialQuantity=function(listId,rowId,itemId,value){const list=b1fSiteMaterialLists().find(row=>row.id===listId),row=list?.rows.find(item=>item.id===rowId);if(!row)return;row.quantities||(row.quantities={});row.quantities[itemId]=b1fSiteMaterialNumber(value);list.updatedAt=b1fNow();b1fSiteMaterialSave();document.querySelectorAll('[data-b1f-estimate-total="'+CSS.escape(itemId)+'"]').forEach(cell=>cell.textContent=b1fSiteMaterialTotal(list,itemId));};

// 其他叫料：只屬於單一工地用料單，保留日後完工處理／加入 B1F 的欄位，但目前不串接任何 B1F 流程。
function b1fOtherOrders(list){return(list.otherOrders||=([]));}
function b1fOtherOrderNumber(value){const number=Number(value);return Number.isFinite(number)&&number>0?number:0;}
function b1fOtherOrderAmount(row){return row.chargeable?(b1fOtherOrderNumber(row.quantity)*b1fOtherOrderNumber(row.unitPrice)):0;}
function b1fOtherOrderTotal(list){return b1fOtherOrders(list).reduce((total,row)=>total+b1fOtherOrderAmount(row),0);}
function b1fOtherOrderMarkup(list){const rows=b1fOtherOrders(list);const rowHtml=rows.map(row=>{const charged=!!row.chargeable,amount=b1fOtherOrderAmount(row);return `<tr>
  <td><input class="b1f-input" value="${escAttr(row.vendor||'')}" placeholder="例如：XX 五金" aria-label="廠商" onchange="updateB1FOtherOrder('${list.id}','${row.id}','vendor',this.value)"></td>
  <td><input class="b1f-input" value="${escAttr(row.name||'')}" placeholder="輸入品名" aria-label="品名" onchange="updateB1FOtherOrder('${list.id}','${row.id}','name',this.value)"></td>
  <td><input class="b1f-row-qty" type="number" min="0" step="any" value="${b1fOtherOrderNumber(row.quantity)}" aria-label="${escAttr(row.name||'其他叫料')} 數量" oninput="updateB1FOtherOrder('${list.id}','${row.id}','quantity',this.value,true)"></td>
  <td><input class="b1f-input" value="${escAttr(row.note||'')}" placeholder="選填" aria-label="備註" onchange="updateB1FOtherOrder('${list.id}','${row.id}','note',this.value)"></td>
  <td><select class="b1f-input" aria-label="計價狀態" onchange="updateB1FOtherOrder('${list.id}','${row.id}','chargeable',this.value)"><option value="no" ${charged?'':'selected'}>不計價</option><option value="yes" ${charged?'selected':''}>計價</option></select></td>
  <td>${charged?`<input class="b1f-row-qty" type="number" min="0" step="any" value="${b1fOtherOrderNumber(row.unitPrice)}" aria-label="${escAttr(row.name||'其他叫料')} 單價" oninput="updateB1FOtherOrder('${list.id}','${row.id}','unitPrice',this.value,true)">`:'<span style="color:var(--text3)">不需輸入</span>'}</td>
  <td style="font-weight:700;color:${charged?'#8d3030':'var(--text3)'}"><span data-b1f-other-amount="${escAttr(row.id)}">${charged?b1fMoney(amount):'—'}</span></td>
  <td><button class="btn btn-sm btn-danger" type="button" onclick="deleteB1FOtherOrder('${list.id}','${row.id}')">刪除</button></td>
</tr>`;}).join('');
  return `<section style="margin-top:24px;padding-top:20px;border-top:2px solid #eadede"><div style="display:flex;justify-content:space-between;gap:12px;align-items:start;flex-wrap:wrap"><div><h3 style="margin:0;color:#7d3030;font-size:16px">其他叫料</h3><p style="margin:6px 0 0;color:var(--text2);font-size:13px">記錄此工地另外向廠商叫的材料或五金；不會建立或影響 B1F 商品資料。</p></div><button class="btn btn-p" type="button" onclick="addB1FOtherOrder('${list.id}')">＋新增其他叫料</button></div><div style="margin-top:14px;overflow:auto;border:1px solid #efd6d6;border-radius:9px"><table style="border-collapse:collapse;width:max-content;min-width:100%"><thead><tr>${['廠商','品名','數量','備註','計價狀態','單價','金額','操作'].map(label=>`<th style="padding:10px;text-align:left;white-space:nowrap;background:#fff8f8;color:#7d3030;font-size:12px;border-bottom:1px solid #efdede">${label}</th>`).join('')}</tr></thead><tbody>${rowHtml||'<tr><td colspan="8" style="padding:18px;text-align:center;color:var(--text3)">尚無其他叫料，請按右上角新增。</td></tr>'}</tbody><tfoot><tr><td colspan="6" style="padding:11px;background:#fff8f8;color:#7d3030;font-weight:700;text-align:right;border-top:1px solid #efdede">計價項目總金額</td><td data-b1f-other-total style="padding:11px;background:#fff8f8;color:#8d3030;font-weight:700;border-top:1px solid #efdede">${b1fMoney(b1fOtherOrderTotal(list))}</td><td style="background:#fff8f8;border-top:1px solid #efdede"></td></tr></tfoot></table></div></section>`;
}
window.addB1FOtherOrder=function(listId){const list=b1fSiteMaterialLists().find(row=>row.id===listId);if(!list)return;b1fOtherOrders(list).push({id:b1fId('other_order'),vendor:'',name:'',quantity:1,note:'',chargeable:false,unitPrice:0,status:'planned',completion:null,b1fItemId:null,createdAt:b1fNow(),updatedAt:b1fNow()});list.updatedAt=b1fNow();b1fSiteMaterialSave();renderB1F();};
window.updateB1FOtherOrder=function(listId,rowId,key,value,live){const list=b1fSiteMaterialLists().find(row=>row.id===listId),row=b1fOtherOrders(list||{}).find(item=>item.id===rowId);if(!row)return;if(key==='chargeable')row.chargeable=value==='yes';else if(key==='quantity'||key==='unitPrice')row[key]=b1fOtherOrderNumber(value);else row[key]=String(value||'');row.updatedAt=b1fNow();list.updatedAt=b1fNow();b1fSiteMaterialSave();if(!live){renderB1F();return;}const amount=b1fOtherOrderAmount(row);document.querySelectorAll('[data-b1f-other-amount="'+CSS.escape(rowId)+'"]').forEach(cell=>cell.textContent=row.chargeable?b1fMoney(amount):'—');document.querySelectorAll('[data-b1f-other-total]').forEach(cell=>cell.textContent=b1fMoney(b1fOtherOrderTotal(list)));};
window.deleteB1FOtherOrder=function(listId,rowId){const list=b1fSiteMaterialLists().find(row=>row.id===listId);if(!list||!confirm('確定刪除此筆其他叫料？'))return;list.otherOrders=b1fOtherOrders(list).filter(row=>row.id!==rowId);list.updatedAt=b1fNow();b1fSiteMaterialSave();renderB1F();};
function b1fSiteMaterialDetailMarkupV3(list){const systemMarkup=b1fSiteMaterialDetailMarkupV2?b1fSiteMaterialDetailMarkupV2(list):b1fSiteMaterialDetailMarkup(list);return systemMarkup.replace('</section>',b1fOtherOrderMarkup(list)+'</section>');}
const b1fSiteMaterialDetailMarkupV2=b1fSiteMaterialDetailMarkup;
b1fSiteMaterialDetailMarkup=b1fSiteMaterialDetailMarkupV3;

// 系統五金與既有 B1F 購物車／領用／退貨的關聯。預估值只供參考，所有實際數量皆由既有使用紀錄累計。
function b1fSiteMaterialUsageStats(list,itemId){const records=(b1fData().usages||[]).filter(row=>row.siteMaterialListId===list.id&&row.itemId===itemId);const issued=records.reduce((sum,row)=>sum+(Number(row.issuedQty)||0),0),returned=records.reduce((sum,row)=>sum+(Number(row.returnedQty)||0),0);return{issued,returned,used:issued-returned};}
function b1fSiteMaterialUsageFooter(list){return '<tr>'+['系統五金實際領用／退貨'].map(label=>'<td style="padding:10px;background:#fff8f8;color:#7d3030;font-weight:700;border-top:1px solid #efdede">'+label+'</td>').join('')+b1fData().items.map(item=>{const stats=b1fSiteMaterialUsageStats(list,item.id),estimate=b1fSiteMaterialTotal(list,item.id),disabled=Number(item.stockQty)<=0?'disabled':'';return '<td style="padding:10px;background:#fff8f8;border-top:1px solid #efdede;vertical-align:top"><div style="font-size:12px;line-height:1.7"><div>預估：<strong>'+estimate+'</strong>'+escAttr(item.unit)+'</div><div>已領：<strong>'+stats.issued+'</strong>'+escAttr(item.unit)+'　已退：<strong>'+stats.returned+'</strong>'+escAttr(item.unit)+'</div><div style="color:#8d3030">實際使用：<strong>'+stats.used+'</strong>'+escAttr(item.unit)+'</div></div><div style="display:flex;gap:5px;margin-top:7px"><input id="b1f-site-cart-qty-'+escAttr(list.id)+'-'+escAttr(item.id)+'" class="b1f-row-qty" type="number" min="1" max="'+item.stockQty+'" step="any" value="1" aria-label="'+escAttr(item.name)+' 本次加入購物車數量" '+disabled+'><button class="btn btn-sm btn-p" type="button" '+disabled+' onclick="addB1FSiteMaterialToCart(\''+list.id+'\',\''+item.id+'\')">加入購物車</button></div></td>';}).join('')+'</tr>';}
const b1fSiteMaterialDetailMarkupV4Source=b1fSiteMaterialDetailMarkup;
b1fSiteMaterialDetailMarkup=function(list){return b1fSiteMaterialDetailMarkupV4Source(list).replace('</tfoot>',b1fSiteMaterialUsageFooter(list)+'</tfoot>');};
window.addB1FSiteMaterialToCart=function(listId,itemId){const list=b1fSiteMaterialLists().find(row=>row.id===listId),item=b1fItem(itemId),input=$('b1f-site-cart-qty-'+listId+'-'+itemId),qty=Number(input?.value);if(!list||!item||!Number.isFinite(qty)||qty<=0||qty>item.stockQty)return alert('本次數量必須大於 0，且不得超過目前 B1F 庫存。');const cart=b1fCart(),linked=cart.find(line=>line.siteMaterialListId);if((linked&&linked.siteMaterialListId!==listId)||(cart.length&&b1fCartProjectId&&b1fCartProjectId!==list.projectId))return alert('購物車已有其他工地用料單的商品，請先完成或清空既有購物車。');const line=cart.find(row=>row.itemId===itemId),next=(line?.qty||0)+qty;if(line&&line.siteMaterialListId!==listId)return alert('此商品已由其他來源加入購物車，請先完成或移除該品項。');if(next>item.stockQty)return alert(item.name+' 加入後會超過目前庫存 '+item.stockQty+item.unit+'。');if(line)line.qty=next;else cart.push({itemId,qty,siteMaterialListId:list.id,siteMaterialProjectId:list.projectId});b1fCartProjectId=list.projectId;b1fSaveCartV5();b1fFlash='已加入購物車：'+item.name+' ×'+qty+item.unit+'（'+list.projectName+'）';b1fView='cart';renderB1F();};
const b1fCartMarkupV8=b1fCartMarkup;
b1fCartMarkup=function(){const linked=b1fCart().find(line=>line.siteMaterialListId),list=linked&&b1fSiteMaterialLists().find(row=>row.id===linked.siteMaterialListId),notice=list?'<div class="b1f-summary" style="margin:0 0 12px">此購物車已連結工地用料單：<strong>'+escAttr(list.projectName)+'</strong>。完成既有「確認領用」後才會計入已領數量。</div>':'';return b1fCartMarkupV8().replace('</label>','</label>'+notice);};
window.confirmB1FCart=async function(){const project=S.projects.find(p=>p.id===$('b1f-cart-project')?.value),cartLines=b1fCart().map(line=>({...line}));if(!project)return alert('請選擇施工中案件。');if(!cartLines.length)return alert('購物車目前沒有商品。');const linkedIds=[...new Set(cartLines.map(line=>line.siteMaterialListId).filter(Boolean))];if(linkedIds.length>1)return alert('同一張購物車一次只能處理一張工地用料單。');const linkedList=linkedIds.length?b1fSiteMaterialLists().find(row=>row.id===linkedIds[0]):null;if(linkedList&&project.id!==linkedList.projectId)return alert('此購物車已連結「'+linkedList.projectName+'」，請使用相同案件完成領用。');try{const result=await b1fCommit(store=>{const lines=cartLines.map(line=>({line,item:store.items.find(item=>item.id===line.itemId)})),invalid=lines.find(x=>!x.item||!Number.isFinite(x.line.qty)||x.line.qty<=0||x.line.qty>x.item.stockQty);if(invalid)throw new Error(invalid?.item?invalid.item.name+' 庫存不足，請調整數量後再確認。':'商品已不存在。');const batchId=b1fId('batch'),now=b1fNow(),order={id:b1fId('order'),batchId,orderNo:'B1F-'+new Date().toISOString().slice(0,10).replaceAll('-','')+'-'+String(store.orders.filter(o=>String(o.orderNo||'').startsWith('B1F-'+new Date().toISOString().slice(0,10).replaceAll('-',''))).length+1).padStart(3,'0'),projectId:project.id,projectName:project.name,createdAt:now,actorId:currentUser?.uid||'',actorName:currentUser?.displayName||'',usageIds:[]};lines.forEach(({line,item})=>{item.stockQty-=line.qty;const amount=line.qty*item.unitPrice,record={id:b1fId('usage'),batchId,orderId:order.id,orderNo:order.orderNo,itemId:item.id,itemName:item.name,unit:item.unit,unitPrice:item.unitPrice,projectId:project.id,projectName:project.name,siteMaterialListId:line.siteMaterialListId||'',siteMaterialProjectId:line.siteMaterialProjectId||'',issuedQty:line.qty,inUseQty:line.qty,returnedQty:0,usedQty:0,disposedQty:0,chargeAmount:amount,refundedAmount:0,status:'pending',issuedAt:now};store.usages.push(record);order.usageIds.push(record.id);b1fLogIn(store,'issue',{batchId,orderId:order.id,usageId:record.id,itemId:item.id,itemName:item.name,quantity:line.qty,unit:item.unit,projectId:project.id,projectName:project.name,amount,siteMaterialListId:record.siteMaterialListId});if(amount>0)b1fLogIn(store,'charge',{batchId,orderId:order.id,usageId:record.id,itemId:item.id,itemName:item.name,quantity:line.qty,unit:item.unit,projectId:project.id,projectName:project.name,amount,siteMaterialListId:record.siteMaterialListId});});store.orders.push(order);return{order,total:lines.reduce((sum,x)=>sum+x.line.qty*x.item.unitPrice,0)};});const cart=b1fCart();cart.splice(0,cart.length);if(!localTestMode)b1fPersonalCart=cart;b1fSaveCartV5();b1fFlash='訂單 '+result.order.orderNo+' 已完成｜本次總金額 '+b1fMoney(result.total);b1fView='pending';renderB1F();}catch(error){if(error?.message)alert(error.message);}};

// 其他叫料完工處理：僅在確認時將剩料轉入 B1F，資料保留工地來源與處理明細以防止重複執行。
function b1fOtherOrderStatus(row){return row.status==='used'?'使用完畢':row.status==='transferred'?'已加入 B1F':'未結案';}
function b1fOtherOrderStatusMarkup(row){const status=row.status||'open',done=row.completion||{};if(status==='used')return '<div><span class="tag" style="background:#e5f5eb;color:#197044">使用完畢</span><div style="margin-top:5px;font-size:11px;color:var(--text3)">叫料 '+b1fOtherOrderNumber(row.quantity)+'｜未入 B1F</div></div>';if(status==='transferred')return '<div><span class="tag" style="background:#eee8ff;color:#5638a5">已加入 B1F</span><div style="margin-top:5px;font-size:11px;color:var(--text3)">叫料 '+b1fOtherOrderNumber(row.quantity)+'｜使用 '+b1fOtherOrderNumber(done.usedQty)+'｜加入 B1F '+b1fOtherOrderNumber(done.remainingQty)+'</div></div>';return '<span class="tag" style="background:#fff1d8;color:#9a5b00">未結案</span>';}
const b1fOtherOrderMarkupV1=b1fOtherOrderMarkup;
b1fOtherOrderMarkup=function(list){const rows=b1fOtherOrders(list);const rowHtml=rows.map(row=>{const charged=!!row.chargeable,amount=b1fOtherOrderAmount(row),open=!['used','transferred'].includes(row.status);return `<tr>
  <td><input class="b1f-input" value="${escAttr(row.vendor||'')}" placeholder="例如：XX 五金" aria-label="廠商" ${open?'':'disabled'} onchange="updateB1FOtherOrder('${list.id}','${row.id}','vendor',this.value)"></td>
  <td><input class="b1f-input" value="${escAttr(row.name||'')}" placeholder="輸入品名" aria-label="品名" ${open?'':'disabled'} onchange="updateB1FOtherOrder('${list.id}','${row.id}','name',this.value)"></td>
  <td><input class="b1f-row-qty" type="number" min="0" step="any" value="${b1fOtherOrderNumber(row.quantity)}" aria-label="${escAttr(row.name||'其他叫料')} 數量" ${open?'':'disabled'} oninput="updateB1FOtherOrder('${list.id}','${row.id}','quantity',this.value,true)"></td>
  <td><input class="b1f-input" value="${escAttr(row.note||'')}" placeholder="選填" aria-label="備註" ${open?'':'disabled'} onchange="updateB1FOtherOrder('${list.id}','${row.id}','note',this.value)"></td>
  <td><select class="b1f-input" aria-label="計價狀態" ${open?'':'disabled'} onchange="updateB1FOtherOrder('${list.id}','${row.id}','chargeable',this.value)"><option value="no" ${charged?'':'selected'}>不計價</option><option value="yes" ${charged?'selected':''}>計價</option></select></td>
  <td>${charged?`<input class="b1f-row-qty" type="number" min="0" step="any" value="${b1fOtherOrderNumber(row.unitPrice)}" aria-label="${escAttr(row.name||'其他叫料')} 單價" ${open?'':'disabled'} oninput="updateB1FOtherOrder('${list.id}','${row.id}','unitPrice',this.value,true)">`:'<span style="color:var(--text3)">不需輸入</span>'}</td>
  <td style="font-weight:700;color:${charged?'#8d3030':'var(--text3)'}"><span data-b1f-other-amount="${escAttr(row.id)}">${charged?b1fMoney(amount):'—'}</span></td>
  <td>${b1fOtherOrderStatusMarkup(row)}</td>
  <td>${open?`<div style="display:flex;gap:5px;flex-wrap:wrap"><button class="btn btn-sm" type="button" onclick="completeB1FOtherOrder('${list.id}','${row.id}')">使用完畢</button><button class="btn btn-sm btn-p" type="button" onclick="openB1FOtherOrderTransfer('${list.id}','${row.id}')">加入 B1F</button><button class="btn btn-sm btn-danger" type="button" onclick="deleteB1FOtherOrder('${list.id}','${row.id}')">刪除</button></div>`:'<span style="font-size:11px;color:var(--text3)">已結案，避免重複處理</span>'}</td>
</tr>`;}).join('');return `<section style="margin-top:24px;padding-top:20px;border-top:2px solid #eadede"><div style="display:flex;justify-content:space-between;gap:12px;align-items:start;flex-wrap:wrap"><div><h3 style="margin:0;color:#7d3030;font-size:16px">其他叫料</h3><p style="margin:6px 0 0;color:var(--text2);font-size:13px">叫料完成後可標記使用完畢，或將剩料加入 B1F；已結案資料會鎖定以避免重複入庫。</p></div><button class="btn btn-p" type="button" onclick="addB1FOtherOrder('${list.id}')">＋新增其他叫料</button></div><div style="margin-top:14px;overflow:auto;border:1px solid #efd6d6;border-radius:9px"><table style="border-collapse:collapse;width:max-content;min-width:100%"><thead><tr>${['廠商','品名','數量','備註','計價狀態','單價','金額','完工狀態','操作'].map(label=>`<th style="padding:10px;text-align:left;white-space:nowrap;background:#fff8f8;color:#7d3030;font-size:12px;border-bottom:1px solid #efdede">${label}</th>`).join('')}</tr></thead><tbody>${rowHtml||'<tr><td colspan="9" style="padding:18px;text-align:center;color:var(--text3)">尚無其他叫料，請按右上角新增。</td></tr>'}</tbody><tfoot><tr><td colspan="7" style="padding:11px;background:#fff8f8;color:#7d3030;font-weight:700;text-align:right;border-top:1px solid #efdede">計價項目總金額</td><td data-b1f-other-total style="padding:11px;background:#fff8f8;color:#8d3030;font-weight:700;border-top:1px solid #efdede">${b1fMoney(b1fOtherOrderTotal(list))}</td><td style="background:#fff8f8;border-top:1px solid #efdede"></td></tr></tfoot></table></div></section>`;};
function b1fOtherOrderRow(listId,rowId){const list=b1fSiteMaterialLists().find(row=>row.id===listId),row=b1fOtherOrders(list||{}).find(item=>item.id===rowId);return{list,row};}
window.completeB1FOtherOrder=function(listId,rowId){const {list,row}=b1fOtherOrderRow(listId,rowId);if(!list||!row||['used','transferred'].includes(row.status))return;const qty=b1fOtherOrderNumber(row.quantity);row.status='used';row.completion={type:'used',orderedQty:qty,usedQty:qty,remainingQty:0,completedAt:b1fNow()};row.updatedAt=b1fNow();list.updatedAt=b1fNow();b1fLogIn(b1fData(),'site_material_other_used',{projectId:list.projectId,projectName:list.projectName,siteMaterialListId:list.id,itemName:row.name||'未命名其他叫料',quantity:qty,unit:row.unit||'',amount:null,note:'其他叫料使用完畢'});b1fSiteMaterialSave();renderB1F();};
window.openB1FOtherOrderTransfer=function(listId,rowId){const {list,row}=b1fOtherOrderRow(listId,rowId);if(!list||!row||['used','transferred'].includes(row.status))return;const existing=b1fData().items.find(item=>String(item.name||'').trim().toLocaleLowerCase()===String(row.name||'').trim().toLocaleLowerCase());const qty=b1fOtherOrderNumber(row.quantity),price=row.chargeable?b1fOtherOrderNumber(row.unitPrice):0;$('mo-content').innerHTML=`<div class="mo-title">其他叫料剩料加入 B1F</div><div class="mo-sub">${escAttr(list.projectName)}｜${escAttr(row.name||'未命名品項')}</div><div class="b1f-form"><label class="b1f-field">剩餘數量<input id="b1f-other-transfer-qty" type="number" min="0.01" max="${qty}" step="any" value="${qty}"></label>${existing?`<div class="b1f-summary"><div class="b1f-summary-row"><span>找到既有商品</span><strong>${escAttr(existing.name)}</strong></div><div class="b1f-summary-row"><span>目前庫存</span><span>${existing.stockQty}${escAttr(existing.unit)}</span></div></div>`:`<label class="b1f-field">B1F 單位<input id="b1f-other-transfer-unit" value="個" placeholder="例如：個、組、支"></label><label class="b1f-field">來源<input id="b1f-other-transfer-source" value="${escAttr(list.projectName)}｜其他叫料剩料"></label><label class="b1f-field">單價<input id="b1f-other-transfer-price" type="number" min="0" step="any" value="${price}"></label><div class="mo-sub">${row.chargeable?'已帶入原叫料單價。':'不計價叫料會建立為 0 元商品。'}</div>`}<div class="mo-footer"><button class="btn" onclick="closeMo()">取消</button><button class="btn btn-p" onclick="confirmB1FOtherOrderTransfer('${list.id}','${row.id}','${existing?.id||''}')">確認加入 B1F</button></div></div>`;$('modal').style.display='flex';};
window.confirmB1FOtherOrderTransfer=function(listId,rowId,existingId){const {list,row}=b1fOtherOrderRow(listId,rowId);const remaining=b1fOtherOrderNumber($('b1f-other-transfer-qty')?.value),ordered=b1fOtherOrderNumber(row?.quantity);if(!list||!row||['used','transferred'].includes(row.status)||remaining<=0||remaining>ordered)return alert('剩餘數量必須大於 0，且不得超過叫料數量。');const used=ordered-remaining;let target=b1fData().items.find(item=>item.id===existingId);if(target){target.stockQty=(Number(target.stockQty)||0)+remaining;}else{const unit=$('b1f-other-transfer-unit')?.value.trim(),source=$('b1f-other-transfer-source')?.value.trim(),price=b1fOtherOrderNumber($('b1f-other-transfer-price')?.value);if(!row.name?.trim()||!unit)return alert('請補齊品名與 B1F 單位。');target={id:b1fId('item'),name:row.name.trim(),categoryIds:[],stockQty:remaining,unit,unitPrice:price,source:source||list.projectName+'｜其他叫料剩料',note:'由工地用料單其他叫料剩料轉入',createdAt:b1fNow()};b1fData().items.push(target);}row.status='transferred';row.completion={type:'b1f',orderedQty:ordered,usedQty:used,remainingQty:remaining,targetItemId:target.id,completedAt:b1fNow()};row.updatedAt=b1fNow();list.updatedAt=b1fNow();b1fLogIn(b1fData(),'site_material_other_to_b1f',{projectId:list.projectId,projectName:list.projectName,siteMaterialListId:list.id,itemId:target.id,itemName:row.name,quantity:remaining,unit:target.unit,amount:null,note:'其他叫料｜叫料 '+ordered+'｜實際使用 '+used+'｜加入 B1F '+remaining});b1fSiteMaterialSave();closeMo();b1fFlash='其他叫料剩料已加入 B1F：'+target.name+' ×'+remaining+target.unit;renderB1F();};
const b1fTypeLabelV8=b1fTypeLabel;
b1fTypeLabel=function(type){return type==='site_material_other_used'?'其他叫料使用完畢':type==='site_material_other_to_b1f'?'其他叫料剩料加入 B1F':b1fTypeLabelV8(type);};

// 系統五金項目可依工地挑選；未選的 B1F 商品不顯示在此張預估表。
function b1fSystemItemsForList(list){const all=b1fData().items;return Array.isArray(list.systemItemIds)?all.filter(item=>list.systemItemIds.includes(item.id)):all;}
function filterB1FSiteMaterialColumns(list){const table=document.querySelector('#panel-b1f section table');if(!table)return;const all=b1fData().items,keep=new Set(b1fSystemItemsForList(list).map(item=>item.id));const removeIndexes=all.map((item,index)=>keep.has(item.id)?-1:index+2).filter(index=>index>0).sort((a,b)=>b-a);table.querySelectorAll('thead tr,tbody tr').forEach(row=>removeIndexes.forEach(index=>row.children[index]?.remove()));}
const b1fSiteMaterialDetailMarkupV5=b1fSiteMaterialDetailMarkup;
b1fSiteMaterialDetailMarkup=function(list){const html=b1fSiteMaterialDetailMarkupV5(list).replace('</h2>','</h2><button class="btn btn-sm" type="button" style="margin-top:8px" onclick="editB1FSystemItems(\''+list.id+'\')">編輯系統五金項目</button>');setTimeout(()=>filterB1FSiteMaterialColumns(list),0);return html;};
window.editB1FSystemItems=function(listId){const list=b1fSiteMaterialLists().find(row=>row.id===listId);if(!list)return;const chosen=new Set(Array.isArray(list.systemItemIds)?list.systemItemIds:b1fData().items.map(item=>item.id));$('mo-content').innerHTML='<div class="mo-title">編輯系統五金項目</div><div class="mo-sub">勾選此工地要顯示與預估的 B1F 商品。</div><div class="b1f-form">'+b1fData().items.map(item=>'<label style="display:flex;gap:8px;align-items:center"><input type="checkbox" name="b1f-system-item" value="'+escAttr(item.id)+'" '+(chosen.has(item.id)?'checked':'')+'>'+escAttr(item.name)+'</label>').join('')+'<div class="mo-footer"><button class="btn" onclick="closeMo()">取消</button><button class="btn btn-p" onclick="saveB1FSystemItems(\''+list.id+'\')">儲存</button></div></div>';$('modal').style.display='flex';};
window.saveB1FSystemItems=function(listId){const list=b1fSiteMaterialLists().find(row=>row.id===listId);if(!list)return;list.systemItemIds=[...document.querySelectorAll('input[name="b1f-system-item"]:checked')].map(input=>input.value);list.updatedAt=b1fNow();b1fSiteMaterialSave();closeMo();renderB1F();};
b1fSiteMaterialUsageFooter=function(list){const items=b1fSystemItemsForList(list);return '<tr><td style="padding:10px;background:#fff8f8;color:#7d3030;font-weight:700;border-top:1px solid #efdede">已領數量<br>已退數量<br><span style="color:#8d3030">實際使用</span><br><button class="btn btn-sm btn-p" style="margin-top:7px" onclick="addAllB1FSiteMaterialToCart(\''+list.id+'\')">全部加入購物車</button></td>'+items.map(item=>{const s=b1fSiteMaterialUsageStats(list,item.id),disabled=Number(item.stockQty)<=0?'disabled':'';return '<td style="padding:10px;background:#fff8f8;border-top:1px solid #efdede;vertical-align:top;text-align:center"><div>'+s.issued+'</div><div>'+s.returned+'</div><div style="color:#8d3030;font-weight:700">'+s.used+'</div><div style="display:flex;gap:5px;margin-top:7px"><input id="b1f-site-cart-qty-'+escAttr(list.id)+'-'+escAttr(item.id)+'" class="b1f-row-qty" type="number" min="0" max="'+item.stockQty+'" step="any" value="0" aria-label="'+escAttr(item.name)+' 本次加入購物車數量" '+disabled+'><button class="btn btn-sm btn-p" type="button" '+disabled+' onclick="addB1FSiteMaterialToCart(\''+list.id+'\',\''+item.id+'\')">加入購物車</button></div></td>';}).join('')+'</tr>';};
window.addAllB1FSiteMaterialToCart=function(listId){const list=b1fSiteMaterialLists().find(row=>row.id===listId),cart=b1fCart();if(!list)return;const inputs=b1fSystemItemsForList(list).map(item=>({item,qty:Number($('b1f-site-cart-qty-'+list.id+'-'+item.id)?.value)||0})).filter(row=>row.qty>0);if(!inputs.length)return alert('請先輸入至少一個要加入購物車的數量。');if(inputs.some(row=>row.qty>row.item.stockQty))return alert('部分數量超過目前 B1F 庫存。');const linked=cart.find(line=>line.siteMaterialListId);if((linked&&linked.siteMaterialListId!==list.id)||(cart.length&&b1fCartProjectId&&b1fCartProjectId!==list.projectId))return alert('購物車已有其他工地用料單的商品，請先完成或清空既有購物車。');for(const {item,qty} of inputs){const line=cart.find(row=>row.itemId===item.id);if(line&&line.siteMaterialListId!==list.id)return alert('購物車已有其他來源的相同商品。');if((line?.qty||0)+qty>item.stockQty)return alert(item.name+' 加入後會超過庫存。');if(line)line.qty+=qty;else cart.push({itemId:item.id,qty,siteMaterialListId:list.id,siteMaterialProjectId:list.projectId});}b1fCartProjectId=list.projectId;b1fSaveCartV5();b1fFlash='已將 '+inputs.length+' 項系統五金加入購物車（'+list.projectName+'）';b1fView='cart';renderB1F();};

// B1F WIP 介面微調：系統五金預設有價商品，表格編輯和其他叫料排序均只影響這張工地用料單。
let b1fSiteMaterialEditMode=false;
// B1F 獨立測試頁不會載入工程進度模組，因此補上共用 Modal 的安全關閉入口。
window.closeMo=window.closeMo||function(){$('modal').style.display='none';$('mo-content').innerHTML='';};
function b1fDefaultSystemItemIds(){return b1fData().items.filter(item=>Number(item.unitPrice)>0).map(item=>item.id);}
b1fSystemItemsForList=function(list){const all=b1fData().items;return Array.isArray(list.systemItemIds)?all.filter(item=>list.systemItemIds.includes(item.id)):all.filter(item=>Number(item.unitPrice)>0);};

const b1fCreateSiteMaterialListV2=window.createB1FSiteMaterialList;
window.createB1FSiteMaterialList=function(){const projectId=$('b1f-site-project')?.value,project=S.projects.find(row=>row.id===projectId);if(!project)return alert('請先選擇施工中案件。');const existing=b1fSiteMaterialLists().find(list=>list.projectId===projectId);if(existing){b1fSiteMaterialListId=existing.id;renderB1F();return;}const list={id:b1fId('site_material'),projectId:project.id,projectName:project.name,rows:[],systemItemIds:b1fDefaultSystemItemIds(),createdAt:b1fNow(),updatedAt:b1fNow()};b1fSiteMaterialLists().push(list);b1fSiteMaterialSave();b1fSiteMaterialListId=list.id;renderB1F();};

const b1fDeleteSiteMaterialRowV2=window.deleteB1FSiteMaterialRow;
window.deleteB1FSiteMaterialRow=function(listId,rowId){if(!b1fSiteMaterialEditMode)return;b1fDeleteSiteMaterialRowV2(listId,rowId);};
window.finishB1FSiteMaterialEdit=function(){b1fSiteMaterialEditMode=false;renderB1F();};

b1fSiteMaterialUsageFooter=function(list){const items=b1fSystemItemsForList(list);return '<tr><td style="padding:10px;background:#fff8f8;color:#7d3030;font-weight:700;border-top:1px solid #efdede">已領數量<br>已退數量<br><span style="color:#8d3030">實際使用</span><br><button class="btn btn-sm btn-p" type="button" style="margin-top:7px" onclick="addAllB1FSiteMaterialToCart(\''+list.id+'\')">全部加入購物車</button></td>'+items.map(item=>{const s=b1fSiteMaterialUsageStats(list,item.id),disabled=Number(item.stockQty)<=0?'disabled':'';return '<td style="padding:10px;background:#fff8f8;border-top:1px solid #efdede;vertical-align:top;text-align:center"><div>'+s.issued+'</div><div>'+s.returned+'</div><div style="color:#8d3030;font-weight:700">'+s.used+'</div><div style="margin-top:7px"><input id="b1f-site-cart-qty-'+escAttr(list.id)+'-'+escAttr(item.id)+'" class="b1f-row-qty" type="number" min="0" max="'+item.stockQty+'" step="any" value="0" aria-label="'+escAttr(item.name)+' 本次加入購物車數量" '+disabled+'></div></td>';}).join('')+'</tr>';};

const b1fSiteMaterialDetailMarkupV6=b1fSiteMaterialDetailMarkup;
b1fSiteMaterialDetailMarkup=function(list){const editControl=b1fSiteMaterialEditMode?'<button class="btn btn-sm" type="button" style="margin:8px 0 0 6px" onclick="finishB1FSiteMaterialEdit()">完成編輯</button>':'';const html=b1fSiteMaterialDetailMarkupV6(list).replace('編輯系統五金項目</button>','編輯系統五金項目</button>'+editControl);setTimeout(()=>{filterB1FSiteMaterialColumns(list);document.querySelectorAll('#panel-b1f button[aria-label="刪除此圖紙頁數或項目"]').forEach(button=>{button.style.display=b1fSiteMaterialEditMode?'':'none';});const otherSection=[...document.querySelectorAll('#panel-b1f h3')].find(heading=>heading.textContent.trim()==='其他叫料')?.closest('section');const vendorHeader=otherSection?.querySelector('thead th:first-child');if(vendorHeader&&!vendorHeader.querySelector('.b1f-vendor-sort'))vendorHeader.insertAdjacentHTML('beforeend',' <button class="btn btn-sm b1f-vendor-sort" type="button" onclick="sortB1FOtherOrdersByVendor(\''+list.id+'\')">排序</button>');},0);return html;};

window.editB1FSystemItems=function(listId){const list=b1fSiteMaterialLists().find(row=>row.id===listId);if(!list)return;b1fSiteMaterialEditMode=true;const chosen=new Set(Array.isArray(list.systemItemIds)?list.systemItemIds:b1fDefaultSystemItemIds());$('mo-content').innerHTML='<div class="mo-title">編輯系統五金項目</div><div class="mo-sub">預設只勾選有金額的商品；取消勾選即代表此工地不需要該項目，不會刪除 B1F 商品。</div><div class="b1f-form">'+b1fData().items.map(item=>'<div style="display:flex;align-items:center;justify-content:space-between;gap:10px"><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" name="b1f-system-item" value="'+escAttr(item.id)+'" '+(chosen.has(item.id)?'checked':'')+'>'+escAttr(item.name)+'</label><button class="btn btn-sm btn-danger" type="button" onclick="removeB1FSystemItemFromEditor(this)">刪除</button></div>').join('')+'<div class="mo-footer"><button class="btn" type="button" onclick="closeB1FSystemItemsEditor()">取消</button><button class="btn btn-p" type="button" onclick="saveB1FSystemItems(\''+list.id+'\')">儲存</button></div></div>';$('modal').style.display='flex';document.onkeydown=function(event){if(event.key==='Escape'&&$('modal')?.style.display==='flex')closeB1FSystemItemsEditor();};};
window.removeB1FSystemItemFromEditor=function(button){const checkbox=button.closest('div')?.querySelector('input[name="b1f-system-item"]');if(!checkbox)return;checkbox.checked=false;button.closest('div').style.opacity='.55';};
window.closeB1FSystemItemsEditor=function(){document.onkeydown=null;closeMo();renderB1F();};
window.saveB1FSystemItems=function(listId){const list=b1fSiteMaterialLists().find(row=>row.id===listId);if(!list)return;list.systemItemIds=[...document.querySelectorAll('input[name="b1f-system-item"]:checked')].map(input=>input.value);list.updatedAt=b1fNow();b1fSiteMaterialSave();document.onkeydown=null;closeMo();renderB1F();};

window.sortB1FOtherOrdersByVendor=function(listId){const list=b1fSiteMaterialLists().find(row=>row.id===listId);if(!list)return;const collator=new Intl.Collator('zh-Hant-u-co-stroke',{numeric:true,sensitivity:'base'});list.otherOrders=b1fOtherOrders(list).map((row,index)=>({row,index})).sort((a,b)=>collator.compare(String(a.row.vendor||''),String(b.row.vendor||''))||a.index-b.index).map(entry=>entry.row);list.updatedAt=b1fNow();b1fSiteMaterialSave();renderB1F();};

// 用料單兩張表格固定在可視範圍內；欄位會依目前系統五金勾選數平均分配，不產生橫向捲軸。
function fitB1FSiteMaterialTables(){
  const panel=$('panel-b1f');
  const systemTable=panel?.querySelector('section table');
  if(systemTable){
    const wrapper=systemTable.parentElement;
    wrapper.style.overflow='hidden';
    systemTable.style.width='100%';
    systemTable.style.minWidth='0';
    systemTable.style.tableLayout='fixed';
    systemTable.querySelectorAll('th,td').forEach(cell=>{cell.style.minWidth='0';});
    const columnCount=systemTable.querySelector('thead tr')?.children.length||0;
    let group=systemTable.querySelector('colgroup');
    if(!group){group=document.createElement('colgroup');systemTable.prepend(group);}
    group.innerHTML=Array.from({length:columnCount},(_,index)=>'<col style="width:'+(index===0?'104px':'auto')+'">').join('');
    systemTable.querySelectorAll('tbody td:first-child .b1f-input').forEach(input=>{input.style.width='90px';input.style.minWidth='0';input.style.maxWidth='90px';});
    systemTable.querySelectorAll('tfoot td:first-child').forEach(cell=>{cell.style.textAlign='center';});
  }
  const otherHeading=[...panel?.querySelectorAll('h3')||[]].find(heading=>heading.textContent.trim()==='其他叫料');
  const otherTable=otherHeading?.closest('section')?.querySelector('table');
  if(!otherTable)return;
  const wrapper=otherTable.parentElement;
  wrapper.style.overflow='hidden';
  otherTable.style.width='100%';
  otherTable.style.minWidth='0';
  otherTable.style.tableLayout='fixed';
  otherTable.querySelectorAll('th,td').forEach(cell=>{cell.style.minWidth='0';overflow='hidden';});
  const widths=['114px','auto','124px','110px','220px'];
  let group=otherTable.querySelector('colgroup');
  if(!group){group=document.createElement('colgroup');otherTable.prepend(group);}
  group.innerHTML=widths.map(width=>'<col style="width:'+width+'">').join('');
  otherTable.querySelectorAll('tbody td').forEach((cell,index)=>{
    const column=index%5;
    const input=cell.querySelector('input,select');
    if(!input)return;
    input.style.minWidth='0';
    input.style.maxWidth='100%';
    if(column===0)input.style.width='90px';
    else if(column===2)input.style.width='100px';
    else input.style.width='100%';
  });
  otherTable.querySelectorAll('tbody td:last-child > div').forEach(actions=>{actions.style.flexWrap='nowrap';actions.style.whiteSpace='nowrap';actions.style.justifyContent='flex-start';});
}
const b1fSiteMaterialDetailMarkupV7=b1fSiteMaterialDetailMarkup;
b1fSiteMaterialDetailMarkup=function(list){const html=b1fSiteMaterialDetailMarkupV7(list);setTimeout(fitB1FSiteMaterialTables,0);return html;};

// 其他叫料不再承擔計價用途：保留舊資料欄位以相容既有紀錄，但不顯示或編輯它們。
b1fOtherOrderMarkup=function(list){const rows=b1fOtherOrders(list);const rowHtml=rows.map(row=>{const open=!['used','transferred'].includes(row.status);return `<tr>
  <td><input class="b1f-input" value="${escAttr(row.vendor||'')}" placeholder="例如：XX 五金" aria-label="廠商" ${open?'':'disabled'} onchange="updateB1FOtherOrder('${list.id}','${row.id}','vendor',this.value)"></td>
  <td><input class="b1f-input" value="${escAttr(row.name||'')}" placeholder="輸入品名" aria-label="品名" ${open?'':'disabled'} onchange="updateB1FOtherOrder('${list.id}','${row.id}','name',this.value)"></td>
  <td><input class="b1f-row-qty" type="number" min="0" step="any" value="${b1fOtherOrderNumber(row.quantity)}" aria-label="${escAttr(row.name||'其他叫料')} 數量" ${open?'':'disabled'} oninput="updateB1FOtherOrder('${list.id}','${row.id}','quantity',this.value,true)"></td>
  <td>${b1fOtherOrderStatusMarkup(row)}</td>
  <td>${open?`<div style="display:flex;gap:5px;flex-wrap:nowrap;white-space:nowrap"><button class="btn btn-sm" type="button" onclick="completeB1FOtherOrder('${list.id}','${row.id}')">使用完畢</button><button class="btn btn-sm btn-p" type="button" onclick="openB1FOtherOrderTransfer('${list.id}','${row.id}')">加入 B1F</button><button class="btn btn-sm btn-danger" type="button" onclick="deleteB1FOtherOrder('${list.id}','${row.id}')">刪除</button></div>`:'<span style="font-size:11px;color:var(--text3)">已結案，避免重複處理</span>'}</td>
</tr>`;}).join('');return `<section style="margin-top:24px;padding-top:20px;border-top:2px solid #eadede"><div style="display:flex;justify-content:space-between;gap:12px;align-items:start;flex-wrap:wrap"><div><h3 style="margin:0;color:#7d3030;font-size:16px">其他叫料</h3><p style="margin:6px 0 0;color:var(--text2);font-size:13px">叫料完成後可標記使用完畢，或將剩料加入 B1F；已結案資料會鎖定以避免重複入庫。</p></div><button class="btn btn-p" type="button" onclick="addB1FOtherOrder('${list.id}')">＋新增其他叫料</button></div><div style="margin-top:14px;overflow:hidden;border:1px solid #efd6d6;border-radius:9px"><table style="border-collapse:collapse;width:auto;min-width:0"><thead><tr>${['廠商','品名','數量','完工狀態','操作'].map(label=>`<th style="padding:10px;text-align:left;white-space:nowrap;background:#fff8f8;color:#7d3030;font-size:12px;border-bottom:1px solid #efdede">${label}</th>`).join('')}</tr></thead><tbody>${rowHtml||'<tr><td colspan="5" style="padding:18px;text-align:center;color:var(--text3)">尚無其他叫料，請按右上角新增。</td></tr>'}</tbody></table></div></section>`;};

// 系統五金的右上操作集中排列，說明文字自然回到標題下方。
const b1fSiteMaterialDetailMarkupV8=b1fSiteMaterialDetailMarkup;
b1fSiteMaterialDetailMarkup=function(list){const edit='<button class="btn btn-sm" type="button" onclick="editB1FSystemItems(\''+list.id+'\')">編輯系統五金項目</button>';const done=b1fSiteMaterialEditMode?'<button class="btn btn-sm" type="button" onclick="finishB1FSiteMaterialEdit()">完成編輯</button>':'';const add='<button class="btn btn-p" type="button" onclick="addB1FSiteMaterialRow(\''+list.id+'\')">＋新增圖紙頁數／項目</button>';let html=b1fSiteMaterialDetailMarkupV8(list);html=html.replace('<button class="btn btn-sm" type="button" style="margin-top:8px" onclick="editB1FSystemItems(\''+list.id+'\')">編輯系統五金項目</button>','').replace('<button class="btn btn-sm" type="button" style="margin:8px 0 0 6px" onclick="finishB1FSiteMaterialEdit()">完成編輯</button>','');html=html.replace(add,'<div style="display:flex;justify-content:flex-end;align-items:center;gap:6px;flex-wrap:wrap">'+edit+done+add+'</div>');html=html.replace('<div style="margin-top:18px;overflow:auto;border:1px solid #efd6d6;border-radius:9px">','<div style="display:flex;justify-content:flex-end;height:28px;margin-top:8px;position:relative;top:-36px"><button class="btn btn-sm" type="button" onclick="openB1FSiteMaterialPrintPreview(\''+list.id+'\')">列印 PDF</button></div><div style="margin-top:-28px;overflow:auto;border:1px solid #efd6d6;border-radius:9px">');return html;};

// 全部加入按鈕與各品項輸入列由同一個控制列起點對齊。
b1fSiteMaterialUsageFooter=function(list){const items=b1fSystemItemsForList(list);return '<tr><td style="padding:10px;background:#fff8f8;color:#7d3030;font-weight:700;border-top:1px solid #efdede;vertical-align:top;text-align:center">已領數量<br>已退數量<br><span style="color:#8d3030">實際使用</span><div style="margin-top:1px;height:38px;display:flex;justify-content:center;align-items:flex-start"><button class="btn btn-sm btn-p" type="button" style="width:84px;min-height:38px;line-height:1.25;text-align:center;padding:4px 6px" onclick="addAllB1FSiteMaterialToCart(\''+list.id+'\')">全部加入<br>購物車</button></div></td>'+items.map(item=>{const s=b1fSiteMaterialUsageStats(list,item.id),disabled=Number(item.stockQty)<=0?'disabled':'';return '<td style="padding:10px;background:#fff8f8;border-top:1px solid #efdede;vertical-align:top;text-align:center"><div>'+s.issued+'</div><div>'+s.returned+'</div><div style="color:#8d3030;font-weight:700">'+s.used+'</div><div style="margin-top:7px;height:38px;display:flex;align-items:flex-start"><input id="b1f-site-cart-qty-'+escAttr(list.id)+'-'+escAttr(item.id)+'" class="b1f-row-qty" style="width:100%;box-sizing:border-box" type="number" min="0" max="'+item.stockQty+'" step="any" value="0" aria-label="'+escAttr(item.name)+' 本次加入購物車數量" '+disabled+'></div></td>';}).join('')+'</tr>';};

function b1fSiteMaterialPrintPreviewMarkup(list){const items=b1fSystemItemsForList(list),number=value=>Number(value)||0,header=items.map(item=>'<th style="padding:7px;border:1px solid #e3dada">'+escAttr(item.name)+'</th>').join(''),rows=list.rows.map(row=>'<tr><td style="padding:7px;border:1px solid #e3dada">'+escAttr(row.label)+'</td>'+items.map(item=>'<td style="padding:7px;border:1px solid #e3dada;text-align:center">'+number(row.quantities?.[item.id])+'</td>').join('')+'</tr>').join(''),totals=items.map(item=>'<td style="padding:7px;border:1px solid #e3dada;text-align:center;font-weight:700">'+b1fSiteMaterialTotal(list,item.id)+'</td>').join(''),usage=items.map(item=>{const stat=b1fSiteMaterialUsageStats(list,item.id);return '<td style="padding:7px;border:1px solid #e3dada;text-align:center">已領 '+stat.issued+'<br>已退 '+stat.returned+'<br><strong>使用 '+stat.used+'</strong></td>';}).join(''),other=b1fOtherOrders(list);return '<div class="mo-title">工地用料單｜列印預覽</div><div class="mo-sub">'+escAttr(list.projectName)+'｜'+new Date().toLocaleDateString('zh-TW')+'</div><div style="max-height:54vh;overflow:auto;margin-top:14px"><h3 style="font-size:14px;margin:0 0 8px">系統五金預估</h3><table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr><th style="padding:7px;border:1px solid #e3dada;text-align:left">圖紙頁數／項目</th>'+header+'</tr></thead><tbody>'+rows+'</tbody><tfoot><tr><td style="padding:7px;border:1px solid #e3dada;font-weight:700">預估總數量</td>'+totals+'</tr><tr><td style="padding:7px;border:1px solid #e3dada;font-weight:700">實際領用／退貨</td>'+usage+'</tr></tfoot></table><h3 style="font-size:14px;margin:18px 0 8px">其他叫料</h3><table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr><th style="padding:7px;border:1px solid #e3dada;text-align:left">廠商</th><th style="padding:7px;border:1px solid #e3dada;text-align:left">品名</th><th style="padding:7px;border:1px solid #e3dada">數量</th><th style="padding:7px;border:1px solid #e3dada">完工狀態</th></tr></thead><tbody>'+(other.length?other.map(row=>'<tr><td style="padding:7px;border:1px solid #e3dada">'+escAttr(row.vendor||'—')+'</td><td style="padding:7px;border:1px solid #e3dada">'+escAttr(row.name||'—')+'</td><td style="padding:7px;border:1px solid #e3dada;text-align:center">'+b1fOtherOrderNumber(row.quantity)+'</td><td style="padding:7px;border:1px solid #e3dada;text-align:center">'+b1fOtherOrderStatus(row)+'</td></tr>').join(''):'<tr><td colspan="4" style="padding:9px;border:1px solid #e3dada;text-align:center">無其他叫料</td></tr>')+'</tbody></table></div><div class="mo-footer"><button class="btn" type="button" onclick="closeMo()">取消</button><button class="btn btn-p" type="button" onclick="printB1FSiteMaterialList(\''+list.id+'\')">開啟系統列印</button></div>';}
window.openB1FSiteMaterialPrintPreview=function(listId){const list=b1fSiteMaterialLists().find(row=>row.id===listId);if(!list)return;$('mo-content').innerHTML=b1fSiteMaterialPrintPreviewMarkup(list);$('modal').style.display='flex';};
window.printB1FSiteMaterialList=function(listId){if(!b1fSiteMaterialLists().some(list=>list.id===listId))return;window.print();};
if(!document.getElementById('b1f-site-material-print-style'))document.head.insertAdjacentHTML('beforeend','<style id="b1f-site-material-print-style">@media print{@page{margin:12mm}#topnav-menu,#panel-b1f .b1f-head,#panel-b1f button,#ai-fab,#modal{display:none!important}body{background:#fff!important}#panel-b1f{padding:0!important}#panel-b1f .b1f-shell>section{border:0!important;padding:0!important}}</style>');
